import{_ as t,a as d}from"./chunks/21-cli-validate.ButpL1-4.js";import{_ as o,o as r,c as a,a2 as c}from"./chunks/framework.BM5YPQmL.js";const E=JSON.parse('{"title":"Command line","description":"","frontmatter":{},"headers":[],"relativePath":"guide/command-line.md","filePath":"guide/command-line.md"}'),n={name:"guide/command-line.md"};function i(l,e,s,m,h,f){return r(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="command-line" tabindex="-1">Command line <a class="header-anchor" href="#command-line" aria-label="Permalink to &quot;Command line&quot;">​</a></h1><p>On Windows use <code>reelforge.cmd</code>; on macOS/Linux <code>./reelforge</code> (or add the folder to your PATH). From a source checkout, <code>pnpm reelforge</code> works everywhere. Every command and option is listed in the <a href="./../reference/cli.html">CLI reference</a>, generated from the command definition itself.</p><p><img src="'+t+'" alt="CLI help"></p><h2 id="main-commands" tabindex="-1">Main commands <a class="header-anchor" href="#main-commands" aria-label="Permalink to &quot;Main commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>reelforge studio [--port &lt;n&gt;] [--host &lt;address&gt;] [--no-open]</code></td><td>Open the project dashboard (default <code>http://127.0.0.1:4310</code>)</td></tr><tr><td><code>reelforge new &lt;id&gt; [--series &lt;name&gt;] [--episode &lt;n&gt;] [--lang en|ar]</code></td><td>Create <code>episodes/&lt;id&gt;/episode.yaml</code> from the blank starter</td></tr><tr><td><code>reelforge new &lt;id&gt; --pack &lt;pack&gt; [--template &lt;t&gt;] [--lang ar] [--slot k=v …]</code></td><td>Create it from an industry template, with draft cues (see <a href="./templates-and-packs.html">Templates</a>)</td></tr><tr><td><code>reelforge packs [--lang en|ar]</code></td><td>List the industry packs, their templates and slots (<code>--json</code> for the full slot definitions)</td></tr><tr><td><code>reelforge edit &lt;id&gt;</code></td><td>Open the visual editor</td></tr><tr><td><code>reelforge cue &lt;id&gt; [--draft]</code></td><td>Open the editor in Cues mode (<code>--draft</code> writes estimated cues instead)</td></tr><tr><td><code>reelforge align &lt;id&gt; [--engine dsp|whisper] [--force] [--dry-run]</code></td><td>Cues for every line and word from the recording (see <a href="./timing.html">Timing</a>)</td></tr><tr><td><code>reelforge align --setup [--model tiny|base|small]</code> / <code>--status</code></td><td>Install / show the optional speech models (one time, ~180 MB)</td></tr><tr><td><code>reelforge dev &lt;id&gt;</code></td><td>Open the editor in Review mode</td></tr><tr><td><code>reelforge mcp [--toolsets basic,design,render]</code></td><td>Run the MCP server for AI assistants (see <a href="./ai.html">AI integration</a>)</td></tr><tr><td><code>reelforge validate &lt;id&gt; [--strict] [--no-measure]</code></td><td>Check everything; exit code 1 on errors (or warnings with <code>--strict</code>)</td></tr><tr><td><code>reelforge render &lt;id&gt; [options]</code> / <code>--all</code></td><td>Render (see <a href="./rendering.html">Rendering and publishing</a>)</td></tr><tr><td><code>reelforge snap &lt;id&gt; &lt;times…&gt; [--every 5] [--cover]</code></td><td>PNG frames + contact sheet; times may be <code>12.5</code>, <code>l7</code>, <code>&quot;l7:&#39;word&#39;&quot;</code></td></tr><tr><td><code>reelforge doctor [--fix]</code></td><td>Check the environment; <code>--fix</code> downloads Chromium</td></tr><tr><td><code>reelforge theme new &lt;name&gt; --accent &lt;#hex&gt; [--mode light|dark] [--font &lt;f&gt;]</code></td><td>Generate a full theme (contrast-checked) from an accent color</td></tr><tr><td><code>reelforge schema [--out &lt;file&gt;]</code></td><td>Write the JSON Schema for editor autocompletion</td></tr></tbody></table><p>Global options: <code>--json</code> (machine-readable output, progress events while rendering), <code>--verbose</code>, <code>--root &lt;folder&gt;</code> (project folder; default: the current folder).</p><p><img src="'+d+'" alt="validate"></p><p><code>reelforge align</code> options: <code>--engine auto|dsp|whisper</code> (auto: Whisper when installed, else pause detection), <code>--model tiny|base|small</code>, <code>--no-vad</code>, <code>--no-words</code> (line cues only), <code>--force</code> (replace cues you marked by hand), <code>--dry-run</code> (print, don&#39;t write). <code>reelforge render --denoise</code> / <code>--no-denoise</code> overrides <code>audio.denoise</code>.</p><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th></tr></thead><tbody><tr><td><code>REELFORGE_ROOT</code></td><td>Project folder</td></tr><tr><td><code>REELFORGE_PRESET</code></td><td>Default preset</td></tr><tr><td><code>REELFORGE_WORKERS</code></td><td>Render processes</td></tr><tr><td><code>REELFORGE_SHARE_SIZE</code></td><td>Share size in MB</td></tr><tr><td><code>REELFORGE_JPEG_QUALITY</code></td><td>Frame capture quality (default 95)</td></tr><tr><td><code>REELFORGE_PORT</code></td><td>Dashboard / studio port</td></tr><tr><td><code>REELFORGE_HOST</code></td><td>Dashboard bind address (default 127.0.0.1)</td></tr><tr><td><code>REELFORGE_ALLOWED_HOSTS</code></td><td>Extra Host names the dashboard accepts (comma separated)</td></tr><tr><td><code>REELFORGE_REQUIRE_TOKEN</code></td><td><code>1</code> requires the bearer token on <code>/mcp</code> and <code>/api/v1</code> everywhere</td></tr><tr><td><code>REELFORGE_NO_OPEN</code></td><td>Do not open the browser automatically</td></tr><tr><td><code>REELFORGE_FFMPEG</code>, <code>REELFORGE_FFPROBE</code></td><td>Paths to ffmpeg / ffprobe</td></tr><tr><td><code>REELFORGE_CHROMIUM</code></td><td>Path to a Chromium executable</td></tr><tr><td><code>REELFORGE_CACHE</code></td><td>Folder for the optional speech models</td></tr><tr><td><code>REELFORGE_CONFIG_DIR</code></td><td>Config folder (<code>llm.json</code>, the server token)</td></tr><tr><td><code>REELFORGE_LLM_*</code></td><td>Language model for scene suggestions (see <a href="./ai.html#models">models</a>)</td></tr><tr><td><code>NO_COLOR</code></td><td>Disable colors</td></tr></tbody></table>',10)])])}const u=o(n,[["render",i]]);export{E as __pageData,u as default};
